code.cpp:
class Solution {
public:
    string shortestCompletingWord(string licensePlate, vector<string>& words) {
        int lp[26] = {0};
        for (char c : licensePlate) {
            if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) {
                char lc = (c >= 'A' && c <= 'Z') ? (char)(c - 'A' + 'a') : c;
                lp[lc - 'a']++;
            }
        }
        string best;
        for (const string& w : words) {
            int wc[26] = {0};
            for (char c : w) {
                wc[c - 'a']++;
            }
            bool ok = true;
            for (int i = 0; i < 26; i++) {
                if (wc[i] < lp[i]) {
                    ok = false;
                    break;
                }
            }
            if (ok && (best.empty() || w.size() < best.size())) {
                best = w;
            }
        }
        return best;
    }
};
